create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role text not null default 'user' check (role in ('admin','user')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function public.current_user_role() returns text language sql stable security definer set search_path = public as $$ select role from public.profiles where id = auth.uid() $$;
alter table public.profiles enable row level security;
create policy "users read own profile" on public.profiles for select to authenticated using (id = auth.uid() or public.current_user_role() = 'admin');
create policy "admins manage profiles" on public.profiles for all to authenticated using (public.current_user_role() = 'admin') with check (public.current_user_role() = 'admin');
drop policy if exists "authenticated experts access" on public.experts; create policy "staff read experts" on public.experts for select to authenticated using (true); create policy "admins manage experts" on public.experts for all to authenticated using (public.current_user_role() = 'admin') with check (public.current_user_role() = 'admin');
drop policy if exists "authenticated cases access" on public.cases; create policy "staff read cases" on public.cases for select to authenticated using (deleted_at is null); create policy "admins manage cases" on public.cases for all to authenticated using (public.current_user_role() = 'admin') with check (public.current_user_role() = 'admin');
drop policy if exists "authenticated deficiencies access" on public.case_deficiencies; create policy "staff read deficiencies" on public.case_deficiencies for select to authenticated using (true); create policy "staff update deficiencies" on public.case_deficiencies for update to authenticated using (public.current_user_role() in ('admin','user')) with check (public.current_user_role() in ('admin','user'));
create or replace function public.refresh_case_status() returns trigger language plpgsql security definer set search_path = public as $$ declare total_count int; resolved_count int; begin select count(*), count(*) filter (where is_resolved) into total_count, resolved_count from public.case_deficiencies where case_id = coalesce(new.case_id, old.case_id); update public.cases set status = case when total_count = 0 then 'no_deficiencies' when resolved_count = total_count then 'completed' else 'needs_review' end, updated_at = now() where id = coalesce(new.case_id, old.case_id); return coalesce(new, old); end $$;
drop trigger if exists deficiency_status_trigger on public.case_deficiencies; create trigger deficiency_status_trigger after insert or update or delete on public.case_deficiencies for each row execute function public.refresh_case_status();
